95	  /**
96	   * Constructs a merkle tree for a single block within a container.
97	   */
98	  private static class BlockMerkleTreeWriter {
99	    // Map of each offset within the block to its chunk info.
100	    // Chunk order in the checksum is determined by their offset.
101	    private final SortedMap<Long, ChunkMerkleTreeWriter> offset2Chunk;
102	    private final long blockID;
103	
104	    BlockMerkleTreeWriter(long blockID) {
105	      this.blockID = blockID;
106	      this.offset2Chunk = new TreeMap<>();
107	    }
108	
109	    /**
110	     * Adds the specified chunks to this block. The offset value of the chunk must be unique within the block,
111	     * otherwise it will overwrite the previous value at that offset.
112	     *
113	     * @param chunks A list of chunks to add to this block.
114	     */
115	    public void addChunks(Collection<ContainerProtos.ChunkInfo> chunks) {
116	      for (ContainerProtos.ChunkInfo chunk: chunks) {
117	        offset2Chunk.put(chunk.getOffset(), new ChunkMerkleTreeWriter(chunk));
118	      }
119	    }
120	
121	    /**
122	     * Uses chunk hashes to compute a block hash for this tree, and returns it as a protobuf object. All block checksum
123	     * computation for the tree happens within this method.
124	     *
125	     * @return A complete protobuf object representation of this block tree.
126	     */
127	    public ContainerProtos.BlockMerkleTree toProto() {
128	      ContainerProtos.BlockMerkleTree.Builder blockTreeBuilder = ContainerProtos.BlockMerkleTree.newBuilder();
129	      ChecksumByteBuffer checksumImpl = CHECKSUM_BUFFER_SUPPLIER.get();
130	      ByteBuffer blockChecksumBuffer = ByteBuffer.allocate(Long.BYTES * offset2Chunk.size());
131	
132	      for (ChunkMerkleTreeWriter chunkTree: offset2Chunk.values()) {
133	        // Ordering of checksums within a chunk is assumed to be in the order they are written.
134	        // This assumption is already built in to the code that reads and writes the values (see
135	        // ChunkInputStream#validateChunk for an example on the client read path).
136	        // There is no other value we can use to sort these checksums, so we assume the stored proto has them in the
137	        // correct order.
138	        ContainerProtos.ChunkMerkleTree chunkTreeProto = chunkTree.toProto();
139	        blockTreeBuilder.addChunkMerkleTree(chunkTreeProto);
140	        blockChecksumBuffer.putLong(chunkTreeProto.getDataChecksum());
141	      }
142	      blockChecksumBuffer.flip();
143	      checksumImpl.update(blockChecksumBuffer);
144	
145	      return blockTreeBuilder
146	          .setBlockID(blockID)
147	          .setDataChecksum(checksumImpl.getValue())
148	          .build();
149	    }
150	  }
